class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int m = matrix.length, n = matrix[0].length;
        int result = Integer.MIN_VALUE;
        for (int c1 = 0; c1 < n; c1++) {
            int[] rowSum = new int[m];
            for (int c2 = c1; c2 < n; c2++) {
                for (int r = 0; r < m; r++) rowSum[r] += matrix[r][c2];
                java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
                set.add(0);
                int prefix = 0;
                for (int s : rowSum) {
                    prefix += s;
                    Integer ceil = set.ceiling(prefix - k);
                    if (ceil != null) result = Math.max(result, prefix - ceil);
                    set.add(prefix);
                }
            }
        }
        return result;
    }
}

class Solution {
    public int maxSumSubmatrix(int[][] matrix, int k) {
        int m = matrix.length, n = matrix[0].length;
        int result = Integer.MIN_VALUE;
        for (int r1 = 0; r1 < m; r1++) {
            int[] colSum = new int[n];
            for (int r2 = r1; r2 < m; r2++) {
                for (int c = 0; c < n; c++) colSum[c] += matrix[r2][c];
                int kadane = kadaneMax(colSum);
                if (kadane <= k) {
                    result = Math.max(result, kadane);
                    if (result == k) return k;
                } else {
                    for (int c1 = 0; c1 < n; c1++) {
                        int sum = 0;
                        for (int c2 = c1; c2 < n; c2++) {
                            sum += colSum[c2];
                            if (sum <= k) result = Math.max(result, sum);
                        }
                    }
                    if (result == k) return k;
                }
            }
        }
        return result;
    }
    private int kadaneMax(int[] arr) {
        int maxSum = arr[0], curSum = arr[0];
        for (int i = 1; i < arr.length; i++) {
            curSum = Math.max(arr[i], curSum + arr[i]);
            maxSum = Math.max(maxSum, curSum);
        }
        return maxSum;
    }
}
